const password = $('Auth API Endpoint1').first().json.body.password;

const strongPassword =
  /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&.#_-])[A-Za-z\d@$!%*?&.#_-]{8,}$/;

const strong = strongPassword.test(password);

return {
  strong: strong
};

